def previous_event_history_source(path, value):
    from handle_baseline_wiring import previous_handle_baseline_source
    value = previous_handle_baseline_source(path, value)
    for current, previous in CHANGES.get(path, ()):
        assert value.count(current) == 1, f"event history hunk changed: {path}"
        value = value.replace(current, previous, 1)
    return value
